29	/** Every Markdown file this repository is the author of. */
30	function markdownFiles(): string[] {
31	  const roots = ["docs", "src/content", "self", ".github/atomaton"];
32	  const found: string[] = [];
33	  const walk = (dir: string) => {
34	    if (!existsSync(dir)) return;
35	    for (const entry of readdirSync(dir)) {
36	      if (entry === "node_modules") continue;
37	      const path = join(dir, entry);
38	      if (statSync(path).isDirectory()) walk(path);
39	      else if (entry.endsWith(".md")) found.push(path);
40	    }
41	  };
42	  for (const root of roots) walk(root);
43	  for (const name of ["README.md", "CONTRIBUTING.md"]) if (existsSync(name)) found.push(name);
44	  return found;
45	}
46	
47	/**
48	 * The link targets in one file, as written.
49	 *
50	 * Inline links only — `[text](target)`. Reference-style definitions are not used
51	 * anywhere in this repository, and a pattern for a form nobody writes is a pattern
52	 * nobody maintains.
53	 *
54	 * Fenced code is stripped first. A README that SHOWS a Markdown link as an example
55	 * is not claiming the target exists, and a test that reads an example as a claim is
56	 * one nobody can satisfy.
57	 */
